# region: intake
def intake(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: digest
def digest(xs, offset=4):
    return [v + offset for v in xs]

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: emit
def emit(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (min(xs) - min(xs)) if xs else 0}

# region: sift
def sift(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return sift(emit(shape(digest(fold(intake(raw))))))

